theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U] [inst_3 : Countable S]
  [inst_4 : MeasurableSingletonClass S] [inst_5 : Countable T] [inst_6 : MeasurableSingletonClass T] {η : Kernel T U}
  {ν : Measure S} [inst_7 : IsProbabilityMeasure ν] {μ : Measure T} [inst_8 : IsZeroOrProbabilityMeasure μ]
  [inst_9 : FiniteSupport μ] [inst_10 : FiniteSupport ν] : Integrable (fun x => Hm[η x.2]) (ν.prod μ) := by
  exact integrable_of_finiteSupport (ν.prod μ)

theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U] [inst_3 : Countable S]
  [inst_4 : MeasurableSingletonClass S] [inst_5 : Countable T] [inst_6 : MeasurableSingletonClass T]
  [inst_7 : Countable U] [inst_8 : MeasurableSingletonClass U] {κ : Kernel T S} {η : Kernel T U}
  [inst_9 : IsZeroOrMarkovKernel κ] [inst_10 : IsZeroOrMarkovKernel η] {μ : Measure T}
  [inst_11 : IsZeroOrProbabilityMeasure μ] (f : S → U) (g : U → S) (h1 : η = κ.map f) (h2 : κ = η.map g)
  [inst_12 : FiniteSupport μ] (hκ : κ.AEFiniteKernelSupport μ) (hη : η.AEFiniteKernelSupport μ) :
  Hk[η , μ] ≤ Hk[κ , μ] := by
  h1]; exact entropy_map_le f hκ

theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U] [inst_3 : Countable S]
  [inst_4 : MeasurableSingletonClass S] [inst_5 : Countable T] [inst_6 : MeasurableSingletonClass T]
  [inst_7 : Countable U] [inst_8 : MeasurableSingletonClass U] {κ : Kernel T S} {η : Kernel T U}
  [inst_9 : IsZeroOrMarkovKernel κ] [inst_10 : IsZeroOrMarkovKernel η] {μ : Measure T}
  [inst_11 : IsZeroOrProbabilityMeasure μ] (f : S → U) (g : U → S) (h1 : η = κ.map f) (h2 : κ = η.map g)
  [inst_12 : FiniteSupport μ] (hκ : κ.AEFiniteKernelSupport μ) (hη : η.AEFiniteKernelSupport μ) :
  Hk[κ , μ] ≤ Hk[η , μ] := by
  h2]; exact entropy_map_le g hη
